impl HourlyEmployee {
    fn calculate_pay(&self) -> f64 {
        let straight_time = std::cmp::min(self.tenths_worked, 400);
        let over_time = self.tenths_worked.saturating_sub(straight_time);
        (straight_time as f64 * self.hourly_rate) + (over_time as f64 * self.hourly_rate * 1.5)
    }
